using System;
using System.IO;
using RoomLab.Native;
using Newtonsoft.Json.Linq;
class Program
{
    static int checks;static void Check(bool v,string message){checks++;if(!v)throw new Exception(message);}
    static void Main(string[] args){var root=Directory.GetCurrentDirectory();var p=NativeProjectLoader.LoadFile(Path.Combine(root,args.Length>0?"Assets/StreamingAssets/RoomLabNative/AuthoredPhysics/authored-physics.json":"Assets/StreamingAssets/RoomLabNative/latest-physics.json"),new ImportOptions{Profile=ImportProfile.CustomDdl13Preserve,RequireAssets=true});foreach(var rules in new[]{NativeGameplayRules.Editor255Compat,NativeGameplayRules.LatestPhysics})foreach(var r in p.Courses[0].Rooms){var g=new NativeMotion(p,p.Courses[0].Id,r.Id,rules);g.Checkpoint.tokens=17;g.Checkpoint.score=1234;g.Checkpoint.recharge=rules==NativeGameplayRules.LatestPhysics?2:7;var save=g.ExportContinuation();var loaded=NativeMotion.FromContinuation(p,JObject.Parse(save.ToString()),rules);Check(loaded.Room.Id==r.Id&&loaded.Tokens==17&&loaded.Score==1234&&loaded.RespawnRemaining==.5,"resource/room continuation");Check(loaded.Checkpoint.state.objects.Count==g.Checkpoint.state.objects.Count&&loaded.Checkpoint.state.zones.Count==g.Checkpoint.state.zones.Count,"mechanisms continuation");loaded.RespawnRemaining=0;loaded.Retry();Check(loaded.Score==1234&&loaded.Tokens==17,"retry after continuation");
        void Reject(Action<JObject> change){var invalid=(JObject)save.DeepClone();change(invalid);bool rejected=false;try{NativeMotion.FromContinuation(p,invalid,rules);}catch{rejected=true;}Check(rejected,"bad save accepted");}
        Reject(v=>v["version"]=999);Reject(v=>v["source"]="other");Reject(v=>v["rules"]="other");Reject(v=>v["room"]="missing");Reject(v=>v["checkpoint"]["charges"]=99);Reject(v=>v["checkpoint"]["state"]["objects"]=new JObject());Reject(v=>v["elapsed"]=double.NaN);Reject(v=>{v["checkpoint"]["x"]=null;v["checkpoint"]["y"]=1e9;});Reject(v=>{v["checkpoint"]["tier"]=-100;v["checkpoint"]["active"]=true;v["checkpoint"]["tokens"]=1;});Reject(v=>v["checkpoint"]["tier"]=3);Reject(v=>v["checkpoint"]["life"]=-1);Reject(v=>v["checkpoint"]["tokens"]=int.MaxValue);Reject(v=>v["checkpoint"]["recharge"]=99);Reject(v=>v["checkpoint"]["x"]="12");Reject(v=>v["deaths"]=-1);Reject(v=>v["checkpoint"]["credited"]=new JArray("unknown/object"));Reject(v=>v["version"]=1);Reject(v=>{v["checkpoint"]["x"]=1e9;v["checkpoint"]["y"]=1e9;});Reject(v=>v["checkpoint"]["tier"]="0");string first=g.Room.Objects[0].Id;Reject(v=>v["current"]["objects"][first]["cooldown"]="NaN");Reject(v=>v["current"]["objects"][first]["standing"]="NaN");Reject(v=>v["current"]["objects"][first]["generation"]=-1);
        g.SetDeveloperOptions(true,true,false);bool blocked=false;try{g.ExportContinuation();}catch{blocked=true;}Check(blocked,"developer save accepted");
    }Console.WriteLine("NATIVE_PROGRESS_PASS checks="+checks+" rooms=11 rules=2");}
}
